__NUXT_JSONP__("/anticorrupcion/noticias/desaparicion_de_la_secretaria_anticorrupcion_es_un_retroceso_advierten_expertos", (function(a,b,c,d){return {data:[{post:{slug:"desaparicion_de_la_secretaria_anticorrupcion_es_un_retroceso_advierten_expertos",title:"Desaparición de la Secretaría Anticorrupción es un retroceso, advierten expertos",date:"2023-04-25T23:15:06.373Z",img:"https:\u002F\u002Fucarecdn.com\u002F0ead3ee6-f7be-413e-9fcd-6a0699925f72\u002F","img-alt":"Dalia Toledo en conferencia de prensa en la Cámara de Diputados",autor:"Dulce Soto, Expansión",link:"https:\u002F\u002Fpolitica.expansion.mx\u002Fmexico\u002F2023\u002F04\u002F25\u002Fdesaparicion-de-la-secretaria-anticorrupcion-es-un-retroceso-advierten-expertos",category:"anticorrupcion",extracto:"Acabar con la Secretaría Ejecutiva del Sistema Nacional Anticorrupción (SESNA) atenta contra los derechos, la Constitución y los acuerdos internacionales que ha suscrito México, indicaron expertos.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Integrantes del Sistema Nacional Anticorrupción (SNA), legisladores y organizaciones civiles alertaron que la desaparición de la Secretaría Ejecutiva de este sistema sería un retroceso y contribuiría a perpetuar la impunidad en el país."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Este órgano coordina la única política pública de largo plazo que busca disminuir los altos niveles de impunidad en la sanción de delitos por corrupción. El impacto sería grave porque en México la impunidad es de 94.8%, afirmó Fernanda Galicia, directora de la organización Mexiro AC."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“El Poder Ejecutivo busca despojarnos de las políticas públicas anticorrupción más importantes. Esta iniciativa pretende borrar 10 años de lucha social para satisfacer a un gobierno que centraliza el poder en el Ejecutivo”, dijo en conferencia de prensa."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"México debe apostar por una lucha contra la corrupción independiente, que no sea política y que no señale solo a los adversarios, mencionó Dalia Toledo, directora de Finanzas Públicas y Políticas Anticorrupción en Ethos. “Y eso requiere instituciones sólidas y apartidistas”, demandó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La iniciativa que el presidente Andrés Manuel López Obrador envió a la Cámara de Diputados para acabar con la Secretaría Ejecutiva del Sistema Nacional Anticorrupción (SESNA) es un retroceso y atenta contra los derechos, la Constitución y los acuerdos internacionales que ha suscrito México, indicaron."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Además, su eliminación obstaculizaría la rendición de cuentas de las 6,900 instituciones públicas de los tres poderes y niveles de gobierno que conectan información a través de ese órgano, advirtió el secretario técnico de la SESNA, Roberto Moreno."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Aunque el presidente Andrés Manuel López Obrador ha argumentado que la SESNA es costosa y duplica funciones, ha logrado ahorros por 1,700 millones de pesos, sostuvo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Y en un futuro, cuando tengamos ya el portal de interconexión de instituciones públicas, vamos a generar un ahorro anual de 10,000 millones de pesos, con lo que podría sobrevivir la Secretaría Ejecutiva por los siguientes 100 años”, expuso Moreno."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Jorge Alberto Alatorre, presidente del Comité de Participación Ciudadana del SNA, pidió a los y las legisladoras, sobre todo a las del partido Morena, dialogar sobre la importancia del Sistema Anticorrupción y no aprobar la iniciativa del presidente de manera arbitraria."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Al unirse a la conferencia, diputados y diputadas del PAN se comprometieron a votar en contra de la propuesta del Ejecutivo federal y, de aprobarse, a interponer acciones de inconstitucionalidad."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Este grupo no va a acompañar el nuevo embate del presidente”, apuntaron."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fdesaparicion_de_la_secretaria_anticorrupcion_es_un_retroceso_advierten_expertos",extension:".md",createdAt:"2023-06-19T05:12:02.087Z",updatedAt:"2023-05-30T23:46:33.654Z"}}],fetch:{},mutations:[]}}("text","element","p","\n")));